/**
 * Custom API Routes
 *
 * This file is the editable surface for custom backend logic that
 * doesn't fit the auto-generated CRUD model (per-model GET/POST/PATCH/
 * DELETE under `/api/<model>s`). Anything you mount on the exported
 * Hono app shows up at `/api/...` alongside the generated CRUD routes.
 *
 * Examples:
 *   - Aggregations / dashboards: `app.get('/dashboard', ...)`
 *   - Webhooks: `app.post('/webhooks/stripe', ...)`
 *   - Auth flows: `app.post('/auth/login', ...)`
 *
 * For installed integrations (Jira, Slack, Google, Meta Ads, etc.):
 *
 * - Dashboards / list views / "my X" pages → mount a route HERE that
 *   uses `getServerToolsClient()`. Resolve identity per request with
 *   `<TOOLKIT>_GET_CURRENT_USER`, compose the calls you need, return
 *   a clean shape your component owns.
 *
 *   The SDK auto-parses tool result `data` on success (the runtime
 *   JSON.stringifies tool responses; @shogo-ai/sdk/tools >=1.3 parses
 *   them back). Index `data` like a plain object — do NOT write a
 *   `JSON.parse(result.data)` helper. Pass a generic to `execute<T>()`
 *   for typed access.
 *
 *   import { getServerToolsClient } from '@shogo-ai/sdk/tools'
 *
 *   app.get('/jira/my-issues', async (c) => {
 *     const tools = getServerToolsClient()
 *     const me = await tools.execute<{ accountId: string }>('JIRA_GET_CURRENT_USER', {})
 *     if (!me.ok || !me.data?.accountId) {
 *       return c.json({ error: me.error ?? 'not authenticated' }, 401)
 *     }
 *     const issues = await tools.execute<{ issues: unknown[] }>('JIRA_SEARCH_ISSUES', {
 *       jql: `assignee = "${me.data.accountId}"`,
 *     })
 *     if (!issues.ok) return c.json({ error: issues.error ?? 'search failed' }, 502)
 *     return c.json({ issues: issues.data?.issues ?? [] })
 *   })
 *
 *   In the browser, surface the server's `error` field — never throw
 *   `new Error('Failed to load X')`:
 *
 *     const res = await fetch('/api/jira/my-issues')
 *     const body = await res.json().catch(() => ({}))
 *     if (!res.ok) setError(body.error ?? `HTTP ${res.status}`)
 *     else setIssues(body.issues ?? [])
 *
 *   After writing or editing a route, hit it to confirm shape + status:
 *     curl -s -w "\nHTTP %{http_code}\n" http://localhost:$RUNTIME_PORT/api/jira/my-issues
 *   A green build proves the file compiled, not that the endpoint works.
 *
 * - Ad-hoc interactive actions (button clicks, form submits) → use
 *   `useTools()` directly in the component. Don't add a route here for
 *   single-call passthroughs.
 *
 * Hand-rolling a `fetch()` to the provider's REST API will fail
 * because the pod has no provider tokens — auth lives in the runtime.
 * NEVER hardcode the agent operator's identity (accountId, member id,
 * userId) into route code; resolve it per request as shown above.
 *
 * The runtime watches this file. Saving triggers a fast restart of
 * `server.tsx` (no schema regeneration, no `prisma db push`) so changes
 * land in under a second.
 *
 * The Prisma client is available — import it from `./src/lib/db`:
 *
 *   import { prisma } from './src/lib/db'
 *
 *   app.get('/stats', async (c) => {
 *     const userCount = await prisma.user.count()
 *     return c.json({ userCount })
 *   })
 *
 * Do NOT edit `server.tsx` — it is auto-generated by the SDK from
 * `shogo.config.json` and will be overwritten on the next regeneration.
 */

import { Hono } from 'hono'
import { prisma } from './src/lib/db'

const app = new Hono()

// ── LLM Usage ──────────────────────────────────────────────
app.get('/llm-usage', async (c) => {
  const { model, provider, from, to, groupBy } = c.req.query()
  const where: Record<string, unknown> = {}
  if (model) where.model = model
  if (provider) where.provider = provider
  if (from || to) {
    where.createdAt = {
      ...(from ? { gte: new Date(from) } : {}),
      ...(to ? { lte: new Date(to) } : {}),
    }
  }

  if (groupBy === 'model') {
    const rows = await prisma.lLMUsage.groupBy({
      by: ['model'],
      _sum: { inputTokens: true, outputTokens: true, totalTokens: true, cost: true },
      _count: true,
      _avg: { latencyMs: true },
      where,
      orderBy: { _sum: { cost: 'desc' } },
    })
    return c.json({ groups: rows })
  }
  if (groupBy === 'provider') {
    const rows = await prisma.lLMUsage.groupBy({
      by: ['provider'],
      _sum: { inputTokens: true, outputTokens: true, totalTokens: true, cost: true },
      _count: true,
      _avg: { latencyMs: true },
      where,
      orderBy: { _sum: { cost: 'desc' } },
    })
    return c.json({ groups: rows })
  }
  if (groupBy === 'hour') {
    const all = await prisma.lLMUsage.findMany({ where, orderBy: { createdAt: 'asc' } })
    const buckets: Record<string, { tokens: number; cost: number; count: number; latency: number; inputTokens: number; outputTokens: number }> = {}
    for (const row of all) {
      const key = new Date(row.createdAt).toISOString().slice(0, 13)
      if (!buckets[key]) buckets[key] = { tokens: 0, cost: 0, count: 0, latency: 0, inputTokens: 0, outputTokens: 0 }
      buckets[key].tokens += row.totalTokens
      buckets[key].cost += row.cost
      buckets[key].count += 1
      buckets[key].latency += row.latencyMs
      buckets[key].inputTokens += row.inputTokens
      buckets[key].outputTokens += row.outputTokens
    }
    const result = Object.entries(buckets).map(([hour, data]) => ({
      hour,
      tokens: data.tokens,
      inputTokens: data.inputTokens,
      outputTokens: data.outputTokens,
      cost: Math.round(data.cost * 10000) / 10000,
      count: data.count,
      avgLatency: data.count > 0 ? Math.round(data.latency / data.count) : 0,
    }))
    return c.json({ timeline: result })
  }

  const items = await prisma.lLMUsage.findMany({
    where,
    orderBy: { createdAt: 'desc' },
    take: 200,
  })
  const summary = await prisma.lLMUsage.aggregate({
    where,
    _sum: { inputTokens: true, outputTokens: true, totalTokens: true, cost: true },
    _count: true,
    _avg: { latencyMs: true },
  })
  return c.json({
    items,
    summary: {
      totalTokens: summary._sum.totalTokens ?? 0,
      inputTokens: summary._sum.inputTokens ?? 0,
      outputTokens: summary._sum.outputTokens ?? 0,
      totalCost: Math.round((summary._sum.cost ?? 0) * 10000) / 10000,
      count: summary._count,
      avgLatency: Math.round(summary._avg.latencyMs ?? 0),
    },
  })
})

app.post('/llm-usage', async (c) => {
  const body = await c.req.json()
  const totalTokens = (body.inputTokens ?? 0) + (body.outputTokens ?? 0)
  const usage = await prisma.lLMUsage.create({
    data: {
      provider: body.provider,
      model: body.model,
      inputTokens: body.inputTokens ?? 0,
      outputTokens: body.outputTokens ?? 0,
      totalTokens,
      cost: body.cost ?? 0,
      latencyMs: body.latencyMs ?? 0,
      status: body.status ?? 'success',
      agentName: body.agentName,
      sessionId: body.sessionId,
      traceId: body.traceId,
      spanId: body.spanId,
      errorMessage: body.errorMessage,
      metadata: body.metadata ? JSON.stringify(body.metadata) : null,
    },
  })
  return c.json(usage, 201)
})

// ── Budget Rules ────────────────────────────────────────────
app.get('/budget-rules', async (c) => {
  const rules = await prisma.budgetRule.findMany({ orderBy: { createdAt: 'desc' } })
  return c.json({ items: rules })
})

app.post('/budget-rules', async (c) => {
  const body = await c.req.json()
  if (body.id) {
    const updated = await prisma.budgetRule.update({ where: { id: body.id }, data: body })
    return c.json(updated)
  }
  const created = await prisma.budgetRule.create({ data: body })
  return c.json(created, 201)
})

app.delete('/budget-rules/:id', async (c) => {
  const id = c.req.param('id')
  await prisma.budgetRule.delete({ where: { id } })
  return c.json({ ok: true })
})

